'use strict';
const API='/api/v2';
const $=s=>document.querySelector(s);
const icons={dashboard:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',activity:'<path d="M3 12h4l3-8 4 16 3-8h4"/>',world:'<circle cx="12" cy="12" r="9"/><path d="M3 12h18M12 3a15 15 0 0 1 0 18M12 3a15 15 0 0 0 0 18"/>',corner:'<path d="M4 5h10a5 5 0 0 1 5 5v9m-4-4 4 4 4-4"/>',route:'<circle cx="6" cy="6" r="2"/><circle cx="18" cy="18" r="2"/><path d="M8 6h6a4 4 0 0 1 0 8h-4a4 4 0 0 0 0 4h6"/>',ban:'<circle cx="12" cy="12" r="9"/><path d="m5.6 5.6 12.8 12.8"/>',shield:'<path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10Z"/><path d="m9 12 2 2 4-4"/>',lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3"/>',users:'<path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M16 3a4 4 0 0 1 0 8M22 21v-2a4 4 0 0 0-3-3.87"/><circle cx="9" cy="7" r="4"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',moon:'<path d="M20.9 13A9 9 0 0 1 11 3.1 9 9 0 1 0 20.9 13Z"/>',logout:'<path d="M9 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h4M16 17l5-5-5-5M21 12H9"/>',refresh:'<path d="M20 11a8 8 0 0 0-14.9-3M4 4v4h4M4 13a8 8 0 0 0 14.9 3M20 20v-4h-4"/>',plus:'<path d="M12 5v14M5 12h14"/>'};
function icon(name){return `<svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.dashboard}</svg>`}
function paintIcons(root=document){root.querySelectorAll('[data-icon]').forEach(el=>{el.innerHTML=icon(el.dataset.icon)})}
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmtBytes=n=>n==null?'—':n>=1073741824?`${(n/1073741824).toFixed(1)} GB`:`${Math.round(n/1048576)} MB`;
const fmtDate=v=>v?new Date(v.replace(' ','T')+(v.includes('Z')||v.includes('+')?'':'Z')).toLocaleString(undefined,{dateStyle:'medium',timeStyle:'short'}):'—';
const state={token:sessionStorage.getItem('bee-token')||localStorage.getItem('bee-token')||'',me:null,tab:'dashboard',data:{},search:'',credential:null,loading:false};
const pages={dashboard:{title:'Dashboard',group:'Overview',description:'Live status of your server and traffic configuration.'},'proxy-hosts':{title:'Proxy hosts',group:'Traffic',description:'Route domains to upstream services with caching and SSL.',add:'Add proxy host',endpoint:'proxy-hosts'},redirections:{title:'Redirections',group:'Traffic',description:'Send domains to a new destination with an HTTP redirect.',add:'Add redirection',endpoint:'redirections'},streams:{title:'Streams',group:'Traffic',description:'Forward TCP and UDP ports to another service.',add:'Add stream',endpoint:'streams'},'dead-hosts':{title:'404 hosts',group:'Traffic',description:'Serve maintenance or unavailable responses for domains.',add:'Add 404 host',endpoint:'dead-hosts'},'access-lists':{title:'Access lists',group:'Security',description:'Limit hosts by IP address and HTTP Basic Auth.',add:'Add access list',endpoint:'access-lists',adminOnly:true},certificates:{title:'Certificates',group:'Security',description:'Manage custom certificates and Let’s Encrypt requests.',add:'Add certificate',endpoint:'certificates',adminOnly:true},users:{title:'Users & SSH',group:'Security',description:'Manage panel access and Linux SSH credentials.',add:'Add user',endpoint:'users',adminOnly:true},audit:{title:'Activity log',group:'Overview',description:'Recent administrative and authentication events.',endpoint:'audit-logs',adminOnly:true}};
function toast(msg,error=false){const el=document.createElement('div');el.className='app-toast'+(error?' error':'');el.textContent=msg;$('#toast-region').append(el);setTimeout(()=>el.remove(),5000)}
async function api(path,opts={}){const response=await fetch(`${API}/${path}`,{...opts,headers:{...(opts.body?{'Content-Type':'application/json'}:{}),...(state.token?{Authorization:`Bearer ${state.token}`}:{})}});let data;const raw=await response.text();try{data=raw?JSON.parse(raw):null}catch{data=raw}if(!response.ok){if(response.status===401&&path!=='auth/login')logout(false);throw new Error(typeof data==='string'?data:(data?.message||`Request failed (${response.status})`))}return data}
function setTheme(theme){document.documentElement.dataset.bsTheme=theme;localStorage.setItem('bee-theme',theme);$('#theme-button').setAttribute('aria-label',theme==='dark'?'Switch to light mode':'Switch to dark mode')}
function showAuth(){state.me=null;$('#app').hidden=true;$('#auth-screen').hidden=false;$('#login-error').hidden=true}
function showApp(){ $('#auth-screen').hidden=true;$('#app').hidden=false;$('#account-name').textContent=state.me.username;$('#account-avatar').textContent=state.me.username.slice(0,1).toUpperCase();document.querySelectorAll('.admin-only').forEach(el=>el.hidden=state.me.role!=='admin');selectTab(state.tab)}
function logout(message=true){state.token='';sessionStorage.removeItem('bee-token');localStorage.removeItem('bee-token');state.data={};showAuth();if(message)toast('Signed out')}
async function init(){setTheme(localStorage.getItem('bee-theme')||'light');paintIcons();$('#login-form').addEventListener('submit',onLogin);$('#logout-button').onclick=()=>logout();$('#password-button').onclick=showPasswordForm;$('#theme-button').onclick=()=>setTheme(document.documentElement.dataset.bsTheme==='dark'?'light':'dark');$('#menu-button').onclick=()=>toggleSidebar(true);$('#close-sidebar').onclick=()=>toggleSidebar(false);$('#sidebar-scrim').onclick=()=>toggleSidebar(false);$('#refresh-button').onclick=()=>loadPage(true);$('#add-button').onclick=()=>openForm(state.tab);$('#modal-close').onclick=closeModal;$('#modal-backdrop').addEventListener('click',e=>{if(e.target.id==='modal-backdrop')closeModal()});document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>selectTab(b.dataset.tab));$('#page-content').addEventListener('click',onPageAction);$('#page-content').addEventListener('input',e=>{if(e.target.id==='list-search'){state.search=e.target.value;filterRows()}});if(state.token){try{state.me=await api('auth/me');showApp()}catch{showAuth()}}else showAuth()}
async function onLogin(e){e.preventDefault();const form=e.currentTarget;const btn=form.querySelector('button[type=submit]');btn.disabled=true;$('#login-error').hidden=true;try{const data=await api('auth/login',{method:'POST',body:JSON.stringify({username:form.username.value.trim(),password:form.password.value})});state.token=data.token;sessionStorage.setItem('bee-token',state.token);state.me=await api('auth/me');form.reset();showApp()}catch(err){$('#login-error').textContent=err.message;$('#login-error').hidden=false}finally{btn.disabled=false}}
function toggleSidebar(open){$('#sidebar').classList.toggle('open',open);$('#sidebar-scrim').hidden=!open}
function selectTab(tab){if(!pages[tab])tab='dashboard';if(pages[tab].adminOnly&&state.me?.role!=='admin')tab='dashboard';state.tab=tab;state.search='';toggleSidebar(false);document.querySelectorAll('[data-tab]').forEach(b=>{b.classList.toggle('active',b.dataset.tab===tab);b.setAttribute('aria-current',b.dataset.tab===tab?'page':'false')});const p=pages[tab];$('#topbar-section').textContent=p.title;$('#page-eyebrow').textContent=p.group;$('#page-title').textContent=p.title;$('#page-description').textContent=p.description;$('#add-button').hidden=!p.add||p.adminOnly&&state.me?.role!=='admin';$('#add-label').textContent=p.add||'';$('#page-content').innerHTML='<div class="loading-state">Loading…</div>';loadPage()}
async function loadPage(refresh=false){const tab=state.tab;const path=pages[tab].endpoint;if(refresh)$('#page-content').innerHTML='<div class="loading-state">Refreshing…</div>';try{if(tab==='dashboard'){const [metrics,proxies,redirects,streams,dead,certs,audit]=await Promise.all([api('metrics'),api('proxy-hosts'),api('redirections'),api('streams'),api('dead-hosts'),api('certificates'),state.me.role==='admin'?api('audit-logs'):Promise.resolve([])]);if(state.tab!==tab)return;Object.assign(state.data,{metrics,'proxy-hosts':proxies,redirections:redirects,streams,'dead-hosts':dead,certificates:certs,audit});renderDashboard();return}const rows=await api(path);if(state.tab!==tab)return;state.data[tab]=rows;renderList(tab,rows);if(tab==='proxy-hosts')await loadChoices();}catch(err){if(state.tab===tab){$('#page-content').innerHTML=`<div class="error-state" role="alert">${esc(err.message)} <button class="btn btn-sm btn-outline-danger ms-2" data-action="retry">Try again</button></div>`;toast(err.message,true)}}}
async function loadChoices(){try{const [certs,lists]=await Promise.all([api('certificates'),api('access-lists')]);state.data.certificates=certs;state.data['access-lists']=lists}catch{}}
function statusBadge(value,good='Active',bad='Inactive'){return `<span class="badge-soft ${value?'green':'red'}">${value?good:bad}</span>`}
function metric(label,value,suffix='',detail='',percent=null){return `<div class="metric-card"><div class="metric-label">${label}</div><div class="metric-value">${value}<span class="metric-suffix">${suffix}</span></div>${percent!=null?`<div class="progress"><div class="progress-bar bg-blue" style="width:${Math.min(100,Math.max(0,percent))}%"></div></div>`:''}<div class="metric-detail">${detail}</div></div>`}
function renderDashboard(){
  const m=state.data.metrics||{};
  const hosts=(state.data['proxy-hosts']||[]).length+(state.data.redirections||[]).length+(state.data['dead-hosts']||[]).length;
  const live=m.nginx_running;
  $('#server-dot').className='status-dot '+(live?'good':'bad');
  $('#server-name').textContent=live?'Nginx running':'Nginx offline';
  $('#topbar-time').textContent=`Updated ${new Date().toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'})}`;
  const recent=(state.data.audit||[]).slice(0,5);
  const metricCards=metric('CPU usage',Number(m.cpu_usage_percent||0).toFixed(1),'%','Across '+(m.cpu_count||0)+' cores',m.cpu_usage_percent)
    +metric('Memory usage',Number(m.memory_usage_percent||0).toFixed(1),'%',`${fmtBytes(m.memory_used_bytes)} of ${fmtBytes(m.memory_total_bytes)}`,m.memory_usage_percent)
    +metric('Disk usage',Number(m.disk_usage_percent||0).toFixed(1),'%',`${fmtBytes(m.disk_used_bytes)} of ${fmtBytes(m.disk_total_bytes)}`,m.disk_usage_percent)
    +metric('Configured hosts',hosts,'','Proxy, redirect & 404 hosts');
  const serverRows=[['Hostname',m.hostname],['Operating system',m.os_name],['Kernel',m.kernel_version],['Nginx',m.nginx_version||'Not detected'],['Uptime',`${Math.floor((m.uptime_seconds||0)/3600)} hours`]];
  const trafficRows=[['Proxy hosts',(state.data['proxy-hosts']||[]).length],['Redirections',(state.data.redirections||[]).length],['TCP / UDP streams',(state.data.streams||[]).length],['404 hosts',(state.data['dead-hosts']||[]).length],['Certificates',(state.data.certificates||[]).length]];
  const kv=rows=>rows.map(([label,value])=>`<div class="kv-row"><span>${label}</span><strong>${esc(value??'—')}</strong></div>`).join('');
  const activity=state.me.role==='admin'?`<div class="section-head"><h2 class="section-title">Recent activity</h2><button class="btn btn-sm btn-ghost-secondary" data-action="audit">View all</button></div>${recent.length?`<div class="table-wrap"><table class="table"><thead><tr><th>Action</th><th>User</th><th>Object</th><th>Time</th></tr></thead><tbody>${recent.map(a=>`<tr><td class="identity">${esc(a.action.replaceAll('_',' '))}</td><td>${esc(a.username)}</td><td class="muted">${esc(a.object_type)} ${esc(a.object_id||'')}</td><td class="muted nowrap">${fmtDate(a.created_at)}</td></tr>`).join('')}</tbody></table></div>`:empty('No activity yet','Events will appear here after panel changes.')}`:'';
  $('#page-content').innerHTML=`<div class="metric-grid">${metricCards}</div><div class="info-grid"><div class="panel"><div class="panel-head"><h2 class="section-title">Server & engine</h2>${statusBadge(live,'Running','Offline')}</div><div class="panel-body">${kv(serverRows)}</div></div><div class="panel"><div class="panel-head"><h2 class="section-title">Traffic setup</h2><span class="text-secondary small">Current configuration</span></div><div class="panel-body">${kv(trafficRows)}</div></div></div>${activity}`;
}
function empty(title,detail){return `<div class="empty-state"><strong>${title}</strong><span>${detail}</span></div>`}
function renderList(tab,rows){const content=$('#page-content');const columns={
'proxy-hosts':['Source domains','Forward target','SSL','Features','Actions'],redirections:['Source domains','Destination','Code','Options','Actions'],streams:['Incoming port','Forward target','Protocol','Status','Actions'],'dead-hosts':['Domains','Response','Message','SSL','Actions'],'access-lists':['Name','IP rules','Basic Auth','Mode','Actions'],certificates:['Name','Provider','Domains','Expiry','Actions'],users:['Username','Role','Shell mode','Created','Actions'],audit:['Action','User','Object','Details','Time']};const filtered=rows.filter(r=>JSON.stringify(r).toLowerCase().includes(state.search.toLowerCase()));content.innerHTML=`<div class="list-toolbar"><input id="list-search" class="form-control" type="search" placeholder="Search ${esc(pages[tab].title.toLowerCase())}…" value="${esc(state.search)}" aria-label="Search ${esc(pages[tab].title)}"><span class="list-count">${filtered.length} ${filtered.length===1?'record':'records'}</span></div>${!filtered.length?empty(state.search?'No matching records':`No ${pages[tab].title.toLowerCase()} yet`,state.search?'Try a different search.':tab==='audit'?'Activity will appear after you make changes.':'Use the Add button to create the first one.'):`<div class="table-wrap"><table class="table"><thead><tr>${columns[tab].map(c=>`<th>${c}</th>`).join('')}</tr></thead><tbody>${filtered.map(r=>rowHtml(tab,r)).join('')}</tbody></table></div>`}`;content.querySelectorAll('tbody tr').forEach(tr=>tr.querySelectorAll('td').forEach((td,index)=>td.dataset.label=columns[tab][index]));}
function filterRows(){renderList(state.tab,state.data[state.tab]||[]);const input=$('#list-search');input.focus();input.setSelectionRange(input.value.length,input.value.length)}
function domains(v){return esc((v||[]).join(', ')||'—')}
function actionBtn(action,id,label,variant='outline-secondary'){return `<button class="btn btn-sm btn-${variant}" data-action="${action}" data-id="${id}">${label}</button>`}
function rowHtml(tab,r){const del=actionBtn('delete',r.id,'Delete','outline-danger');const actions=(other='')=>`<div class="table-actions">${other}${tab==='users'&&r.id===state.me.id?'':del}</div>`;switch(tab){case'proxy-hosts':return `<tr><td class="identity">${domains(r.domain_names)}</td><td class="mono">${esc(r.forward_scheme)}://${esc(r.forward_host)}:${esc(r.forward_port)}</td><td>${r.ssl_certificate_id?'<span class="badge-soft green">SSL</span>':'<span class="badge-soft">HTTP</span>'}</td><td>${[r.caching_enabled?'Cache':'',r.websocket_support?'WebSocket':'',r.block_exploits?'Protection':''].filter(Boolean).map(x=>`<span class="badge-soft me-1">${x}</span>`).join('')||'—'}</td><td>${actions(actionBtn('inspect',r.id,'Details'))}</td></tr>`;case'redirections':return `<tr><td class="identity">${domains(r.domain_names)}</td><td class="mono">${esc(r.forward_scheme)}://${esc(r.forward_domain)}</td><td><span class="badge-soft blue">${esc(r.forward_http_code)}</span></td><td>${r.preserve_path?'Keep path':'Replace path'}</td><td>${actions()}</td></tr>`;case'streams':return `<tr><td class="identity mono">:${esc(r.incoming_port)}</td><td class="mono">${esc(r.forward_host)}:${esc(r.forward_port)}</td><td>${r.tcp_forwarding?'<span class="badge-soft blue me-1">TCP</span>':''}${r.udp_forwarding?'<span class="badge-soft amber">UDP</span>':''}</td><td>${statusBadge(r.is_enabled)}</td><td>${actions()}</td></tr>`;case'dead-hosts':return `<tr><td class="identity">${domains(r.domain_names)}</td><td><span class="badge-soft ${r.status_code===503?'amber':'red'}">${esc(r.status_code)}</span></td><td class="muted">${esc(r.custom_message||'—')}</td><td>${r.ssl_certificate_id?'Enabled':'—'}</td><td>${actions()}</td></tr>`;case'access-lists':return `<tr><td class="identity">${esc(r.name)}</td><td>${(r.items||[]).length} rules</td><td>${(r.auth_users||[]).length} users</td><td>${r.satisfy_any?'Match any':'Match all'}</td><td>${actions(actionBtn('inspect',r.id,'Details'))}</td></tr>`;case'certificates':return `<tr><td class="identity">${esc(r.nice_name)}</td><td><span class="badge-soft blue">${esc(r.provider)}</span></td><td>${domains(r.domain_names)}</td><td class="muted">${r.expires_at?fmtDate(r.expires_at):'—'}</td><td>${state.me.role==='admin'?actions():''}</td></tr>`;case'users':return `<tr><td class="identity">${esc(r.username)}</td><td><span class="badge-soft ${r.role==='admin'?'blue':''}">${esc(r.role)}</span></td><td>${esc(r.shell_mode.replaceAll('_',' '))}</td><td class="muted">${fmtDate(r.created_at)}</td><td>${actions(actionBtn('credentials',r.id,'SSH keys'))}</td></tr>`;case'audit':return `<tr><td class="identity">${esc(r.action.replaceAll('_',' '))}</td><td>${esc(r.username)}</td><td>${esc(r.object_type)} ${esc(r.object_id||'')}</td><td class="muted">${esc(r.details||'—')}</td><td class="muted nowrap">${fmtDate(r.created_at)}</td></tr>`;default:return''}}
async function onPageAction(e){const btn=e.target.closest('[data-action]');if(!btn)return;const action=btn.dataset.action,id=Number(btn.dataset.id);if(action==='retry')return loadPage();if(action==='audit')return selectTab('audit');if(action==='delete')return deleteItem(id);if(action==='credentials')return showCredentials(id);if(action==='inspect')return showDetails(id)}
function openModal(title,kicker,body){$('#modal-title').textContent=title;$('#modal-kicker').textContent=kicker;$('#modal-body').innerHTML=body;$('#modal-backdrop').hidden=false;document.body.style.overflow='hidden';setTimeout(()=>$('#modal-body').querySelector('input,select,textarea,button')?.focus(),10)}
function closeModal(){if($('#modal-backdrop').hidden)return;$('#modal-backdrop').hidden=true;$('#modal-body').innerHTML='';$('#modal-body').onclick=null;document.body.style.overflow=''}
function input(name,label,type='text',extra='',value=''){return `<div><label class="form-label" for="f-${name}">${label}</label><input id="f-${name}" name="${name}" class="form-control" type="${type}" value="${esc(value)}" ${extra}></div>`}
function select(name,label,options){return `<div><label class="form-label" for="f-${name}">${label}</label><select id="f-${name}" name="${name}" class="form-select">${options.map(([v,t])=>`<option value="${esc(v)}">${esc(t)}</option>`).join('')}</select></div>`}
function textarea(name,label,hint='',required=false){return `<div class="span-2"><label class="form-label" for="f-${name}">${label}</label><textarea id="f-${name}" name="${name}" class="form-control" ${required?'required':''}></textarea>${hint?`<div class="form-hint">${hint}</div>`:''}</div>`}
function check(name,label,hint='',checked=false){return `<div class="form-switch-row span-2"><label for="f-${name}">${label}<small>${hint}</small></label><input id="f-${name}" name="${name}" type="checkbox" ${checked?'checked':''}></div>`}
function certOptions(){return [['','No certificate'],...(state.data.certificates||[]).map(c=>[c.id,c.nice_name])]}function accessOptions(){return [['','No access list'],...(state.data['access-lists']||[]).map(c=>[c.id,c.name])]}
async function openForm(tab){if(tab==='certificates'){openModal('Add certificate','Security',`<div class="credential-actions mb-3"><button class="btn btn-primary" data-cert-mode="letsencrypt">Let’s Encrypt</button><button class="btn btn-outline-secondary" data-cert-mode="custom">Custom PEM</button></div><div id="cert-form-area"></div>`);$('#modal-body').onclick=e=>{const b=e.target.closest('[data-cert-mode]');if(b)renderCertForm(b.dataset.certMode)};renderCertForm('letsencrypt');return}if(['proxy-hosts','redirections','dead-hosts'].includes(tab)){await loadChoices()}let fields='';switch(tab){case'proxy-hosts':fields=input('domain_names','Domain names','text','required placeholder="app.your-domain.tld, www.your-domain.tld"')+select('forward_scheme','Forward scheme',[['http','HTTP'],['https','HTTPS']])+input('forward_host','Forward host','text','required placeholder="127.0.0.1"')+input('forward_port','Forward port','number','required min="1" max="65535"','3000')+select('ssl_certificate_id','SSL certificate',certOptions())+select('access_list_id','Access list',accessOptions())+check('caching_enabled','Enable caching','Cache upstream responses')+check('websocket_support','WebSocket support','Pass upgrade headers',true)+check('block_exploits','Block common exploits','Apply Nginx protection rules',true)+check('ssl_forced','Force HTTPS','Redirect HTTP to HTTPS')+check('http2_support','HTTP/2','Enable HTTP/2 when SSL is selected',true)+check('hsts_enabled','HSTS','Send Strict-Transport-Security header')+check('hsts_subdomains','Include subdomains in HSTS','Applies to all subdomains')+textarea('custom_locations','Custom locations','One per line: /path http host port')+(state.me.role==='admin'?textarea('advanced_config','Advanced Nginx directives','Use only trusted directives.'):'');break;case'redirections':fields=input('domain_names','Source domains','text','required placeholder="old.your-domain.tld"')+select('forward_scheme','Destination scheme',[['https','HTTPS'],['http','HTTP']])+input('forward_domain','Destination domain','text','required placeholder="new.your-domain.tld"')+select('forward_http_code','HTTP code',[[301,'301 · Permanent'],[302,'302 · Temporary'],[307,'307 · Temporary, preserve method'],[308,'308 · Permanent, preserve method']])+select('ssl_certificate_id','SSL certificate',certOptions())+check('preserve_path','Preserve path','Keep the original URL path',true)+check('block_exploits','Block common exploits','Apply Nginx protection rules',true);break;case'streams':fields=input('incoming_port','Incoming port','number','required min="1" max="65535"')+input('forward_host','Forward host','text','required placeholder="127.0.0.1"')+input('forward_port','Forward port','number','required min="1" max="65535"')+check('tcp_forwarding','TCP forwarding','Accept TCP traffic',true)+check('udp_forwarding','UDP forwarding','Accept UDP traffic');break;case'dead-hosts':fields=input('domain_names','Domain names','text','required placeholder="offline.your-domain.tld"')+select('status_code','Response code',[[404,'404 · Not found'],[503,'503 · Maintenance'],[410,'410 · Gone']])+select('ssl_certificate_id','SSL certificate',certOptions())+textarea('custom_message','Response message','Plain text shown to visitors.');break;case'access-lists':fields=input('name','List name','text','required')+textarea('items','IP rules','One per line: allow 192.0.2.0/24 or deny 198.51.100.10')+textarea('auth_users','Basic Auth users','One per line: username:password')+check('satisfy_any','Match any rule','Allow if IP or Basic Auth matches')+check('pass_auth_to_host','Pass auth to upstream','Forward credentials after validation');break;case'users':fields=input('username','Username','text','required pattern="[a-zA-Z0-9_-]+"')+input('password','Panel & SSH password','password','autocomplete="new-password" placeholder="Generate automatically"')+select('role','Panel role',[['tenant','Tenant'],['admin','Administrator']])+select('shell_mode','Linux shell mode',[['sftp_only','SFTP only'],['standard_shell','Standard shell'],['sudo_admin','Sudo admin']]);break;default:return}
openModal(pages[tab].add,pages[tab].group,`<form id="create-form"><div class="form-grid">${fields}</div><div id="form-error" class="text-danger small mt-3" role="alert" hidden></div><div class="form-actions"><button type="button" class="btn btn-outline-secondary" id="form-cancel">Cancel</button><button type="submit" class="btn btn-primary">Create</button></div></form>`);$('#form-cancel').onclick=closeModal;$('#create-form').onsubmit=e=>submitForm(e,tab)}
function renderCertForm(mode){const f=mode==='custom'?input('nice_name','Certificate name','text','required')+textarea('cert_pem','Certificate PEM','Include full certificate chain.',true)+textarea('key_pem','Private key PEM','Private key is stored on the server.',true)+textarea('intermediate_pem','Intermediate PEM','Optional.'):input('domain_names','Domain names','text','required placeholder="app.your-domain.tld, www.your-domain.tld"')+input('contact_email','Contact email','email','required')+check('is_staging','Use Let’s Encrypt staging','For testing only; certificate is not trusted');$('#cert-form-area').innerHTML=`<form id="create-form"><div class="form-grid">${f}</div><div id="form-error" class="text-danger small mt-3" role="alert" hidden></div><div class="form-actions"><button type="button" class="btn btn-outline-secondary" id="form-cancel">Cancel</button><button type="submit" class="btn btn-primary">${mode==='custom'?'Upload certificate':'Request certificate'}</button></div></form>`;$('#form-cancel').onclick=closeModal;$('#create-form').onsubmit=e=>submitForm(e,mode==='custom'?'cert-custom':'cert-le')}
const splitDomains=s=>s.split(/[\s,]+/).map(x=>x.trim()).filter(Boolean);const numOrNull=s=>s?Number(s):null;
function formPayload(form,tab){const v=n=>form.elements[n]?.value?.trim()||'';const b=n=>!!form.elements[n]?.checked;switch(tab){case'proxy-hosts':return{domain_names:splitDomains(v('domain_names')),forward_scheme:v('forward_scheme'),forward_host:v('forward_host'),forward_port:Number(v('forward_port')),ssl_certificate_id:numOrNull(v('ssl_certificate_id')),access_list_id:numOrNull(v('access_list_id')),caching_enabled:b('caching_enabled'),websocket_support:b('websocket_support'),block_exploits:b('block_exploits'),ssl_forced:b('ssl_forced'),http2_support:b('http2_support'),hsts_enabled:b('hsts_enabled'),hsts_subdomains:b('hsts_subdomains'),advanced_config:v('advanced_config')||null,custom_locations:v('custom_locations').split('\n').map(s=>s.trim()).filter(Boolean).map(s=>{const parts=s.split(/\s+/);if(parts.length!==4)throw Error('Custom locations must use: /path http host port');return{path:parts[0],forward_scheme:parts[1],forward_host:parts[2],forward_port:Number(parts[3])}})};case'redirections':return{domain_names:splitDomains(v('domain_names')),forward_scheme:v('forward_scheme'),forward_domain:v('forward_domain'),forward_http_code:Number(v('forward_http_code')),ssl_certificate_id:numOrNull(v('ssl_certificate_id')),preserve_path:b('preserve_path'),block_exploits:b('block_exploits')};case'streams':if(!b('tcp_forwarding')&&!b('udp_forwarding'))throw Error('Select TCP or UDP forwarding');return{incoming_port:Number(v('incoming_port')),forward_host:v('forward_host'),forward_port:Number(v('forward_port')),tcp_forwarding:b('tcp_forwarding'),udp_forwarding:b('udp_forwarding')};case'dead-hosts':return{domain_names:splitDomains(v('domain_names')),status_code:Number(v('status_code')),ssl_certificate_id:numOrNull(v('ssl_certificate_id')),custom_message:v('custom_message')||null};case'access-lists':return{name:v('name'),items:v('items').split('\n').map(x=>x.trim()).filter(Boolean).map(x=>{const m=x.match(/^(allow|deny)\s+(.+)$/i);if(!m)throw Error('IP rules must use: allow 192.0.2.0/24');return{directive:m[1].toLowerCase(),address:m[2]}}),auth_users:v('auth_users').split('\n').map(x=>x.trim()).filter(Boolean).map(x=>{const at=x.indexOf(':');if(at<=0||at===x.length-1)throw Error('Basic Auth users must use: username:password');return{username:x.slice(0,at),password:x.slice(at+1)}}),satisfy_any:b('satisfy_any'),pass_auth_to_host:b('pass_auth_to_host')};case'users':return{username:v('username'),password:v('password')||null,role:v('role'),shell_mode:v('shell_mode')};case'cert-le':return{domain_names:splitDomains(v('domain_names')),contact_email:v('contact_email'),is_staging:b('is_staging')};case'cert-custom':return{nice_name:v('nice_name'),cert_pem:v('cert_pem'),key_pem:v('key_pem'),intermediate_pem:v('intermediate_pem')||null}}}
async function submitForm(e,tab){e.preventDefault();const form=e.currentTarget,btn=form.querySelector('[type=submit]'),error=$('#form-error');btn.disabled=true;error.hidden=true;try{const payload=formPayload(form,tab);const endpoint=tab==='cert-le'?'certificates/letsencrypt':tab==='cert-custom'?'certificates/custom':pages[tab].endpoint;const result=await api(endpoint,{method:'POST',body:JSON.stringify(payload)});closeModal();toast(tab==='cert-le'?'Certificate requested':'Created successfully');if(tab==='users'&&result.ssh_credentials)renderCredentials(result.ssh_credentials,result.user.username);await loadPage(true)}catch(err){error.textContent=err.message;error.hidden=false}finally{btn.disabled=false}}
async function deleteItem(id){const tab=state.tab,record=(state.data[tab]||[]).find(x=>x.id===id);if(tab==='users'&&id===state.me.id){toast('You cannot delete your own account',true);return}if(!confirm(`Delete ${tab==='users'?record?.username:record?.nice_name||record?.name||record?.domain_names?.join(', ')||'#'+id}? This cannot be undone.`))return;try{await api(`${pages[tab].endpoint}/${id}`,{method:'DELETE'});toast('Deleted successfully');await loadPage(true)}catch(err){toast(err.message,true)}}
function showDetails(id){const record=(state.data[state.tab]||[]).find(x=>x.id===id);if(!record)return;const exclude=['password_hash','private_key_pem','initial_password'];const body=Object.entries(record).filter(([k])=>!exclude.includes(k)).map(([k,v])=>`<div class="kv-row"><span>${esc(k.replaceAll('_',' '))}</span><strong>${esc(Array.isArray(v)?v.map(x=>typeof x==='object'?JSON.stringify(x):x).join(', '):v===null?'—':typeof v==='object'?JSON.stringify(v):v)}</strong></div>`).join('');openModal('Record details',pages[state.tab].title,body)}
async function showCredentials(id){try{const record=(state.data.users||[]).find(x=>x.id===id);const cred=await api(`users/${id}/credentials`);renderCredentials(cred,record?.username||'user')}catch(err){toast(err.message,true)}}
function renderCredentials(cred,username){state.credential={...cred,username};const host=state.data.metrics?.hostname||location.hostname;openModal(`SSH credentials · ${username}`,'Users & SSH',`<div class="credential-row"><label>SSH command</label><div class="secret-box" id="ssh-command">ssh ${esc(username)}@${esc(host)}</div></div><div class="credential-row"><label>Initial password</label><div class="secret-box" id="ssh-password">${esc(cred.initial_password||'No saved password')}</div></div><div class="credential-row"><label>Public key</label><div class="secret-box" id="ssh-public">${esc(cred.public_key)}</div></div><div class="credential-row"><label>Private key</label><div class="secret-box" id="ssh-private">••••••••••••••••</div></div><div class="credential-actions"><button id="reveal-key" class="btn btn-outline-secondary">Reveal key</button><button id="copy-key" class="btn btn-outline-secondary">Copy key</button><button id="download-key" class="btn btn-primary">Download PEM</button><button id="rotate-key" class="btn btn-outline-danger">Rotate SSH key</button></div>`);$('#reveal-key').onclick=()=>{$('#ssh-private').textContent=state.credential.private_key_pem};$('#copy-key').onclick=async()=>{await navigator.clipboard.writeText(state.credential.private_key_pem);toast('Private key copied')};$('#download-key').onclick=()=>{const blob=new Blob([state.credential.private_key_pem],{type:'application/x-pem-file'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`${username}_id_ed25519.pem`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};$('#rotate-key').onclick=async()=>{if(!confirm(`Rotate SSH key for ${username}? The old key will stop working.`))return;try{const updated=await api(`users/${cred.user_id}/rotate-ssh`,{method:'POST'});toast('SSH key rotated');renderCredentials(updated,username)}catch(err){toast(err.message,true)}}}

function showPasswordForm(){
  openModal('Change password','Account',`<form id="password-form"><div class="form-grid">${input('current_password','Current password','password','required autocomplete="current-password"')}${input('new_password','New password','password','required minlength="12" autocomplete="new-password"')}${input('confirm_password','Confirm new password','password','required minlength="12" autocomplete="new-password"')}</div><div id="form-error" class="text-danger small mt-3" role="alert" hidden></div><div class="form-actions"><button type="button" class="btn btn-outline-secondary" id="form-cancel">Cancel</button><button type="submit" class="btn btn-primary">Update password</button></div></form>`);
  $('#form-cancel').onclick=closeModal;
  $('#password-form').onsubmit=async e=>{
    e.preventDefault();
    const form=e.currentTarget,error=$('#form-error'),button=form.querySelector('[type=submit]');
    error.hidden=true;
    if(form.elements.new_password.value!==form.elements.confirm_password.value){error.textContent='Passwords do not match';error.hidden=false;return}
    button.disabled=true;
    try{await api('auth/change-password',{method:'POST',body:JSON.stringify({current_password:form.elements.current_password.value,new_password:form.elements.new_password.value})});closeModal();logout(false);toast('Password updated. Sign in again.')}
    catch(err){error.textContent=err.message;error.hidden=false}finally{button.disabled=false}
  };
}
document.addEventListener('DOMContentLoaded',init);
